import{c as a,Q as r,j as o,m as l}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Language Generation with Replay: A Learning-Theoretic View of Model Collapse","description":"","frontmatter":{"url":"https://arxiv.org/abs/2603.11784","title":"Language Generation with Replay: A Learning-Theoretic View of Model Collapse","archived_date":"2026-07-31T00:00:00.000Z","arxiv_id":2603.11784,"authors":["Giorgio Racca","Michal Valko","Amartya Sanyal"],"domain":"model-collapse-recursive-training","published_date":"2026-03-12T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-07-31-model-collapse-replay-learning-theory-2603-11784.md","filePath":"research/papers/2026-07-31-model-collapse-replay-learning-theory-2603-11784.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-07-31-model-collapse-replay-learning-theory-2603-11784.md"};function i(t,e,p,s,c,d){return r(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="language-generation-with-replay-a-learning-theoretic-view-of-model-collapse" tabindex="-1">Language Generation with Replay: A Learning-Theoretic View of Model Collapse <a class="header-anchor" href="#language-generation-with-replay-a-learning-theoretic-view-of-model-collapse" aria-label="Permalink to &quot;Language Generation with Replay: A Learning-Theoretic View of Model Collapse&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文以學習理論框架研究 model collapse，形式化「replay adversary」——一個把生成器過去輸出重新注入訓練資料流的對手模型。核心發現是分離定理：replay 對不同「生成」概念的威脅程度不同——對 uniform generation（要求覆蓋所有合法輸出）沒有威脅，但對較弱的 non-uniform generation 與 generation-in-the-limit 這兩種較寬鬆的生成保證，replay 可證明地造成能力分離（即模型在這些較弱形式下的生成能力會被自產資料回流破壞）。</p><p>這把「模型會不會崩潰」從純粹經驗問題轉為「你要求的是哪一種生成保證」的定義問題：崩潰不是全有全無的現象，而是與具體生成目標的強度掛鉤。論文進一步將理論結果對應到業界既有防護手段（資料清洗、浮水印），並指出這些手段在特定條件下會失效——即當防護只針對「偵測合成內容」而非「保證特定生成強度」時。論文已被 ICML 2026 接受（v1 2026-03，v2 2026-07 修訂）。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>Workspace 既有覆蓋的 machine-unlearning（2026-07-03，主動移除已學知識）與剛被 Routine E 本輪排除的 continual learning 候選（跨任務知識更新經濟學）皆非本文機制：本文談的是「生成保證的強度」在自產資料回流下如何被分離破壞，這是資料源頭純度與生成目標定義的問題，workspace 全庫對 <code>replay adversary</code>、<code>spectral characterization</code> 等本領域核心術語 0 命中。</p>',6)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
